using TownOfHost;
using UnityEngine;
partial class Program {
 static void ReproduceOptionsModalReset(){var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);Call("Reset",x.menu);Call("BeforeCamera",Camera.main);Check(x.view.Visible&&x.view.OptionsBlocking&&x.ui.IsOpen);Check(!x.menu.playButton.GetComponent<SpriteRenderer>().enabled);Check(!Proxy("Play").Colliders[0].enabled);CloseSettingsSlide(x.ui);Check(x.view.Visible&&!x.view.OptionsBlocking);x.view.Dispose();}

 static void OptionsModalResetTests(){
  Test("settings ownership survives native home ResetScreen before camera",ReproduceOptionsModalReset);
  Test("native menu deactivation beneath settings does not release background lease",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);Call("DeactivatingHome");x.menu.Home=false;Call("BeforeCamera",Camera.main);Check(x.view.Visible&&x.view.OptionsBlocking&&x.ui.IsOpen&&!Proxy("Play").Colliders[0].enabled);x.menu.Home=true;CloseSettingsSlide(x.ui);x.view.Dispose();});
  Test("temporary hide remains owned and camera restores evening behind native settings",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);x.view.Hide();Check(x.view.OptionsBlocking&&!(bool)Call("PopupOpen"));Call("BeforeCamera",Camera.main);Check(x.view.Visible&&x.view.OptionsBlocking&&!x.menu.playButton.GetComponent<SpriteRenderer>().enabled);CloseSettingsSlide(x.ui);x.view.Dispose();});
  Test("native reset cannot reenable proxy colliders while modal is active",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);Call("Reset",x.menu);Proxy("Play").Colliders[0].enabled=true;Call("BeforeCamera",Camera.main);Check(!Proxy("Play").Colliders[0].enabled&&x.row.Colliders[0].enabled);CloseSettingsSlide(x.ui);Check(Proxy("Play").Colliders[0].enabled);x.view.Dispose();});
  Test("native late renderer reset is suppressed before settings camera renders",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);Call("Tick",x.menu);var legacy=x.menu.playButton.GetComponent<SpriteRenderer>();legacy.enabled=true;Call("BeforeCamera",Camera.main);Check(x.view.Visible&&!legacy.enabled&&x.row.GetComponent<SpriteRenderer>().enabled);CloseSettingsSlide(x.ui);x.view.Dispose();});
  Test("modal geometry is unchanged by repeated native resets",()=>{var x=SettingsSlideFixture();var scale=x.ui.transform.localScale;OpenSettingsSlide(x.ui);for(int i=0;i<12;i++){Time.frameCount++;Call("Reset",x.menu);Call("BeforeCamera",Camera.main);Near(x.ui.transform.localScale.x,scale.x);Near(x.ui.transform.localScale.y,scale.y);Check(x.view.Visible&&x.view.OptionsBlocking);}CloseSettingsSlide(x.ui);Near(x.ui.transform.localPosition.y,.3);x.view.Dispose();});
  Test("important popup remains authoritative without losing options lease",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);var error=new GameObject("RequiredError").AddComponent<GenericPopup>();Call("GenericOpening",error);Call("BeforeCamera",Camera.main);Check(!x.view.Visible&&x.view.OptionsBlocking&&(string)Call("BlockingPopup")=="startup");error.gameObject.SetActive(false);Call("StartupPopupClosed");Call("BeforeCamera",Camera.main);Check(x.view.Visible&&x.view.OptionsBlocking&&x.row.Colliders[0].enabled);CloseSettingsSlide(x.ui);x.view.Dispose();});
  Test("settings close after temporary hide returns input on next camera callback",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);x.view.Hide();CloseSettingsSlide(x.ui);Call("BeforeCamera",Camera.main);Check(x.view.Visible&&!x.view.OptionsBlocking&&Proxy("Play").Colliders[0].enabled);x.view.Dispose();});
  Test("temporary hide and disable do not restore an unrelated controller overlay",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);var overlay=new ControllerUiElementsState(){MenuName="CriticalConfirmation",IsScene=false};overlay.CurrentSelection=x.row;overlay.SelectableUiElements.Add(x.row);ControllerManager.Instance.CurrentUiState=overlay;x.view.Hide();Call("BeforeCamera",Camera.main);Check(ControllerManager.Instance.CurrentUiState==overlay&&overlay.CurrentSelection==x.row&&overlay.SelectableUiElements.Count==1);CloseSettingsSlide(x.ui);x.view.Dispose();});
  Test("ordinary deactivation without settings retains existing navigation-away behaviour",()=>{var x=Setup();BindHome(x);Call("DeactivatingHome");Check(!x.view.Visible&&!x.view.OptionsBlocking);x.view.Dispose();});
  Test("actual navigation away releases settings lease",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);Call("LeavingHome");Check(!x.view.Visible&&!x.view.OptionsBlocking);CloseSettingsSlide(x.ui);x.view.Dispose();});
  Test("disposal releases options ownership even while root is already hidden",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);x.view.Hide();x.view.Dispose();Check(!x.view.OptionsBlocking);});
  Test("scene change during native reset never replays evening UI into game",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);x.view.Hide();var legacy=x.menu.playButton.GetComponent<SpriteRenderer>();var previous=legacy.enabled;GameScene();Call("BeforeCamera",Camera.main);Check(Home==null&&!x.view.Visible&&!x.view.OptionsBlocking&&legacy.enabled==previous);});
  Test("late-created proxy collider is blocked only for lifetime of options",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);var root=UnityEngine.Object.Objects.Single(g=>g.name=="ShellSeasideHome");var c=new GameObject("LateControl").AddComponent<BoxCollider2D>();c.transform.SetParent(root.transform,false);Call("BeforeCamera",Camera.main);Check(!c.enabled);CloseSettingsSlide(x.ui);Check(c.enabled);x.view.Dispose();});
  Test("ten reset-open-close cycles never expose native home renderers",()=>{var x=SettingsSlideFixture();for(int i=0;i<10;i++){OpenSettingsSlide(x.ui);Call("Reset",x.menu);Call("BeforeCamera",Camera.main);Check(x.view.Visible&&x.view.OptionsBlocking&&!x.menu.playButton.GetComponent<SpriteRenderer>().enabled);CloseSettingsSlide(x.ui);Call("BeforeCamera",Camera.main);Check(x.view.Visible&&!x.view.OptionsBlocking&&!x.menu.playButton.GetComponent<SpriteRenderer>().enabled&&Proxy("Play").Colliders[0].enabled);}x.view.Dispose();});
  Test("owned native options are not classified as a blocking foreign popup after reset",()=>{var x=SettingsSlideFixture();OpenSettingsSlide(x.ui);Call("Reset",x.menu);Check(Call("BlockingPopup")==null&&!(bool)Call("PopupOpen"));CloseSettingsSlide(x.ui);x.view.Dispose();});
 }
}
